head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnDisabled]<br/>Column 정보를 사용하여 특정 Column 의 disabled 상태를 설정합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 disabled 상태를 설정할 Column 의 인덱스를 설정할 수 있어야 합니다. (Column 의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.)",
        "disabled(선택) 파라미터를 true 로 설정 시 특정 Column 을 disabled 상태로 설정해야 합니다.",
        "disabled(선택) 파라미터를 false 로 설정 시 특정 Column 의 disabled 상태를 해제해야 합니다.",
        "disabled(선택) 파라미터를 ''(빈 문자열)로 설정 시 GridView 의 disabled 상태가 적용되어야 합니다.",
        "disabled(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "setCellDisabled() 메소드로 설정된 Cell 단위 disabled 상태는 Column 단위 disabled 상태보다 우선 적용되어야 합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Cell(0, 0) 은 disabled true 설정 (Cell 우선 검증용) / Column 1 은 숨겨진 상태 / 배경색 회색=disabled"', '', 'label1');

    // 조건 설정 (disabled Cell 을 배경색으로 구분: disabled=회색)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 두번째 컬럼 숨김 (숨겨진 Column 도 인덱스에 포함됨)
    target1.setColumnVisible(1, false);

    // GridView 단위 disabled 를 false 로 설정 (Column 단위 true/false 동작 관찰용)
    target1.setDisabled("grid", false);

    // Cell(0, 0) 에 disabled true 설정 (Cell 단위가 Column 단위보다 우선 적용되는지 검증용)
    target1.setCellDisabled(0, 0, true);
}



scwin.btn_setColumnDisabled_onclick = function () {
    let colInfo = Number(par_colInfo.getValue());
    let disabledText = par_disabled.getValue();

    if (disabledText === 'omit') {
        // 파라미터 생략 (기본값 false)
        target1.setColumnDisabled(colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisabled(" + colInfo + ")");
    } else if (disabledText === '') {
        // 빈 문자열 설정 (GridView 의 disabled 상태 적용)
        target1.setColumnDisabled(colInfo, "");
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisabled(" + colInfo + ", '')");
    } else {
        let disabled = disabledText === 'true';
        target1.setColumnDisabled(colInfo, disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisabled(" + colInfo + ", " + disabled + ")");
    }

    // Column 단위 disabled 상태값 확인
    let colDisabled = target1.getColumnDisabled(colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnDisabled(" + colInfo + ") [Column 단위 상태] : " + colDisabled);

    // 해당 Column 전체 Row 의 실제 적용 disabled 상태 (Column 단위 효과 확인, GridView/Column/Cell 우선순위 반영)
    let rowCount = dlt_bind.getRowCount();
    let states = [];
    for (let r = 0; r < rowCount; r++) {
        states.push("Row" + r + "=" + target1.getDisabled("all", r, colInfo));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("Column " + colInfo + " 전체 적용 상태 : " + states.join(", "));
}
